// Baked ground and tree, so the chase view paints from a file:// page without tainting the canvas.
// Each ground tile is 128 px: at the chase scale a tile covers about that many screen pixels, so a larger
// one was only being shrunk again on every frame.
const SCENE_TEX = {
  grass: "data:image/jpeg;base64,",
  asphalt: "data:image/jpeg;base64,",
  gravel: "data:image/jpeg;base64,",
  concrete: "data:image/jpeg;base64,",
  tree: "data:image/png;base64,"
};
